import { NextRequest, NextResponse } from 'next/server';
import { searchVenues, SearchParams } from '@/lib/google-places';

export const dynamic = 'force-dynamic';

// Primary approach: Use Google Places API with database caching
async function searchLocalVenues(params: SearchParams) {
  console.log(`Searching for ${params.category} venues near ${params.zipCode} within ${params.radius || 20} miles`);

  try {
    // Use Google Places API with caching
    const venues = await searchVenues(params);
    return venues;
  } catch (error) {
    console.error('Google Places API failed, falling back to local data:', error);
    // Fallback to static data if Google Places fails
    return getRealLocalBusinesses(params.zipCode, params.category, params.radius || 20);
  }
}

