export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const zip = searchParams.get('zip');
    const category = searchParams.get('category') || 'indoor';
    const radius = parseInt(searchParams.get('radius') || '20');
    const sortBy = searchParams.get('sortBy') || 'distance';
    const minRating = parseFloat(searchParams.get('minRating') || '0');
    const searchQuery = searchParams.get('search');

    if (!zip) {
      return NextResponse.json({ error: 'ZIP code is required' }, { status: 400 });
    }

    // Validate category
    const validCategories = ['indoor', 'outdoor', 'specialty', 'community'];
    if (!validCategories.includes(category)) {
      return NextResponse.json({ error: 'Invalid category' }, { status: 400 });
    }

    console.log(`Searching for ${category} venues near ${zip} within ${radius} miles`);

    const searchParams: SearchParams = {
      zipCode: zip,
      category: category as 'indoor' | 'outdoor' | 'specialty' | 'community',
      radius,
      minRating: minRating > 0 ? minRating : undefined,
      searchQuery: searchQuery || undefined,
      sortBy: sortBy as 'distance' | 'rating' | 'name' | 'reviews'
    };

    const venues = await searchLocalVenues(searchParams);

